import java.util.LinkedList;

class TaskQueue {
    private final LinkedList<String> tasks = new LinkedList<>();

    void addTask(String task) {
        tasks.addLast(task);
    }

    boolean popAndCheck() {
        tasks.removeFirst();          // command - mutates state
        return tasks.isEmpty();       // query - answers a question
    }
}

public class Main {
    public static void main(String[] args) {
        TaskQueue queue = new TaskQueue();
        queue.addTask("task-1");
        queue.addTask("task-2");

        boolean emptyAfterFirstPop = queue.popAndCheck();
        System.out.println("Empty after first pop: " + emptyAfterFirstPop);

        boolean emptyAfterSecondPop = queue.popAndCheck();
        System.out.println("Empty after second pop: " + emptyAfterSecondPop);
    }
}

