#include <iostream>
#include <deque>
#include <string>

class TaskQueue {
public:
    void addTask(const std::string& task) {
        tasks.push_back(task);
    }

    bool popAndCheck() {
        tasks.pop_front();            // command - mutates state
        return tasks.empty();         // query - answers a question
    }

private:
    std::deque<std::string> tasks;
};

int main() {
    TaskQueue queue;
    queue.addTask("task-1");
    queue.addTask("task-2");

    bool emptyAfterFirstPop = queue.popAndCheck();
    std::cout << "Empty after first pop: " << std::boolalpha << emptyAfterFirstPop << std::endl;

    bool emptyAfterSecondPop = queue.popAndCheck();
    std::cout << "Empty after second pop: " << std::boolalpha << emptyAfterSecondPop << std::endl;

    return 0;
}

