from collections import deque


class TaskQueue:
    def __init__(self):
        self.tasks = deque()

    def add_task(self, task):
        self.tasks.append(task)

    def pop(self):
        self.tasks.popleft()          # command - no return value

    def is_empty(self):
        return len(self.tasks) == 0   # query - no mutation


if __name__ == "__main__":
    queue = TaskQueue()
    queue.add_task("task-1")
    queue.add_task("task-2")

    queue.pop()
    print(f"Empty after first pop: {queue.is_empty()}")

    queue.pop()
    print(f"Empty after second pop: {queue.is_empty()}")

